window, grid, stack { background-color: #FFFFFF; }

.soc-status {
  background-color: rgba(244,248,245,0.92);
  border: 1px solid rgba(31,164,99,0.30);
  border-radius: 10px;
  padding: 18px 28px;
}
.soc-status.error { border-color: rgba(192,52,29,0.55); }

.soc-status-id {
  color: #1FA463;
  font-weight: bold;
  font-size: 12px;
  letter-spacing: 2px;
}
.soc-status.error .soc-status-id { color: #C0341D; }

.soc-status-msg { color: rgba(11,31,20,0.88); font-size: 15px; }
.soc-status.error .soc-status-msg { color: rgba(192,52,29,0.80); }

.soc-status spinner { color: #1FA463; min-width: 22px; min-height: 22px; }

/* on-screen config window + corner gear */
.soc-config { background-color: #FFFFFF; }
.soc-config-title { color: #0B1F14; font-size: 18px; font-weight: bold; }
.soc-config-sub  { color: #5B7567; font-size: 12px; }
.soc-config-tag  { color: #1FA463; font-weight: bold; }
.soc-config-ok    { color: #1FA463; font-size: 12px; }
.soc-config-error { color: #C0341D; font-size: 12px; }
.soc-config entry {
  background-color: #EAF1EC; color: #0B1F14;
  border: 1px solid rgba(31,164,99,0.30); border-radius: 6px; padding: 6px 8px;
}
.soc-config entry:focus { border-color: #1FA463; }
.soc-config button {
  background-image: none; background-color: #F4F8F5; color: rgba(11,31,20,0.88);
  border: 1px solid rgba(31,164,99,0.30); border-radius: 6px; padding: 6px 12px;
}
.soc-config-primary {
  background-color: #157A49; color: #ffffff; border-color: #157A49;
}
.soc-config-sec { color: #5B7567; }

/* Destructive buttons (Remove VPN, Delete vault item, Clear PIN): a subtle red
 * outline + label, so the intent is visible at a glance without screaming. */
.soc-config button.destructive-action,
.destructive-action {
  background-color: #F4F8F5;
  color: #C0341D;
  border-color: rgba(192,52,29,0.50);
}
.soc-config button.destructive-action:hover,
.destructive-action:hover {
  background-color: rgba(192,52,29,0.12);
  border-color: #C0341D;
}

/* toolbar action buttons (Settings, Lock, Shot, VPN log) */
.soc-gear, .soc-toolbar-action {
  background-image: none;
  background-color: rgba(234,241,236,0.72);
  border: 1px solid rgba(31,164,99,0.35);
  border-radius: 8px; padding: 3px 12px; margin: 0 2px;
  color: rgba(91,117,103,0.95); font-size: 13px; font-weight: bold;
}
.soc-gear:hover, .soc-toolbar-action:hover {
  background-color: rgba(31,164,99,0.85); color: #ffffff;
}

/* boot-time file-integrity drift banner (above the toolbar) */
.soc-warn-bar {
  background-color: rgba(184,134,11,0.15);
  border-bottom: 1px solid rgba(184,134,11,0.45);
}
.soc-warn-bar label { color: #B8860B; font-weight: bold; }

/* top toolbar (always-visible controls; webviews can't paint over it) */
.soc-toolbar {
  background-color: rgba(255,255,255,0.92);
  border-bottom: 1px solid rgba(31,164,99,0.18);
  padding: 4px 8px;
}

/* VPN status pill (top of the wall). Traffic-light colours: green=online,
 * amber=connecting (probe timed out, still mid-handshake), red=offline. */
.soc-vpn-pill {
  background-image: none;
  background-color: rgba(234,241,236,0.82);
  border: 1px solid rgba(31,164,99,0.30);
  border-radius: 12px; padding: 3px 14px; margin: 0 2px;
  color: rgba(11,31,20,0.88); font-size: 13px; font-weight: bold;
}
.soc-vpn-pill.online       { border-color: rgba(31,164,99,0.70);   color: #1FA463; }
.soc-vpn-pill.connecting   { border-color: rgba(184,134,11,0.75); color: #B8860B; }
.soc-vpn-pill.offline      { border-color: rgba(192,52,29,0.70);  color: #C0341D; }
.soc-vpn-pill.checking     { color: #B8860B; }
.soc-vpn-pill.unconfigured { color: #5B7567; }

/* Settings notebook tabs: match the palette, so they aren't a black-on-black
   default-theme artifact inside the themed settings window. */
notebook header { background-color: #FFFFFF; border-bottom: 1px solid #CFE0D4; }
notebook tab { background-color: #FFFFFF; color: #5B7567; padding: 6px 14px;
  border: 1px solid transparent; border-bottom: none; }
notebook tab:checked { background-color: #F4F8F5; color: #0B1F14;
  border-color: #CFE0D4; }
notebook tab:hover { color: #1FA463; }

